 "content": "def transform(grid):
    # Color 9 (or 3 in this instance) forms separators; each of the nine
    # panels is marked when it contains more than one 5.
    h, w = len(grid), len(grid[0])
    sep_rows = [r for r, row in enumerate(grid) if all(v == 9 for v in row)]
    sep_cols = [c for c in range(w) if all(grid[r][c] == 9 for r in range(h))]
    # In the test, separators are 3s; derive them as full uniform rows/columns
    # distinct from the panel background (0) and marker (5).
    if not sep_rows:
        sep_rows = [r for r, row in enumerate(grid) if len(set(row)) == 1 and row[0] not in (0, 5)]
    if not sep_cols:
        sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] not in (0, 5)]
    rb = [-1] + sep_rows + [h]
    cb = [-1] + sep_cols + [w]
    out = [[3 for _ in range(len(cb)-1)] for _ in range(len(rb)-1)]
    for i in range(len(rb)-1):
        for j in range(len(cb)-1):
            n = sum(grid[r][c] == 5
                    for r in range(rb[i]+1, rb[i+1])
                    for c in range(cb[j]+1, cb[j+1]))
            if n > 1:
                out[i][j] = 1
    return out
